#include <iostream>
#include <thread>
#include <chrono>
#include <cstring>
#include <nav2_util/lifecycle_node.hpp>
#include <sensor_msgs/msg/point_cloud2.hpp>
#include "layers.cpp"
void need(bool x,const char*s){if(!x)throw std::runtime_error(s);}
int main(int argc,char**argv){if(!std::getenv("ROS_DOMAIN_ID")||std::string(std::getenv("ROS_DOMAIN_ID"))!="165")return 2;rclcpp::init(argc,argv);try{
 rclcpp::NodeOptions opt;opt.parameter_overrides({rclcpp::Parameter("inflation.chassis_mask_file",std::string(argv[1])),rclcpp::Parameter("inflation.escape_sparse_enabled",true),rclcpp::Parameter("inflation.inflation_radius",.5)});auto n=std::make_shared<nav2_util::LifecycleNode>("sparse_native_fixture","",opt);tf2_ros::Buffer tf(n->get_clock());rclcpp::executors::SingleThreadedExecutor ex;ex.add_node(n->get_node_base_interface());auto lease=n->create_publisher<sensor_msgs::msg::PointCloud2>("/pb/escape/sparse_lease",1);lease->on_activate();nav2_costmap_2d::LayeredCostmap layered("odom",false,false);layered.resizeMap(300,300,.02,-3.,-3.);std::vector<geometry_msgs::msg::Point>foot;for(auto xy:{std::pair<double,double>{-.1,-.1},{.1,-.1},{.1,.1},{-.1,.1}}){geometry_msgs::msg::Point p;p.x=xy.first;p.y=xy.second;foot.push_back(p);}layered.setFootprint(foot);arx_base_mask::InflationLayer l;l.initialize(&layered,"inflation",&tf,n,n->create_callback_group(rclcpp::CallbackGroupType::MutuallyExclusive));auto&g=*layered.getCostmap();
 auto msg=[&](int count=1){sensor_msgs::msg::PointCloud2 m;m.header.frame_id="odom";m.header.stamp=n->now();m.height=1;m.width=count;m.point_step=12;m.row_step=12*count;m.data.resize(12*count);for(unsigned i=0;i<3;++i){sensor_msgs::msg::PointField f;f.name=i==0?"x":i==1?"y":"z";f.offset=i*4;f.datatype=7;f.count=1;m.fields.push_back(f);}for(int j=0;j<count;++j){float p[3]={1.01f+.02f*j,.21f,0.f};std::memcpy(m.data.data()+12*j,p,12);}return m;};
 auto publish=[&](const auto&m){lease->publish(m);for(int i=0;i<6;++i){ex.spin_some();std::this_thread::sleep_for(std::chrono::milliseconds(10));}};
 unsigned x,y,fx,fy;g.worldToMap(1.01,.21,x,y);g.worldToMap(2.,1.,fx,fy);auto cycle=[&](int cluster=1,bool unknown=false){g.resetMap(0,0,300,300);for(int i=0;i<cluster;++i)g.setCost(x+i,y,unknown?255:254);g.setCost(fx,fy,254);double a=0,b=0,c=0,d=0;l.updateBounds(0,0,0,&a,&b,&c,&d);l.updateCosts(g,0,0,300,300);};
 auto three=msg(3);for(int i=0;i<3;++i){float p[3]={1.01f+.4f*i,.21f,0.f};std::memcpy(three.data.data()+12*i,p,12);}publish(three);g.resetMap(0,0,300,300);for(int i=0;i<3;++i){unsigned a,b;g.worldToMap(1.01+.4*i,.21,a,b);g.setCost(a,b,254);}double aa=0,bb=0,cc=0,dd=0;l.updateBounds(0,0,0,&aa,&bb,&cc,&dd);l.updateCosts(g,0,0,300,300);need(g.getCost(x,y)==254,"more than two isolated clusters accepted");
 auto first=msg();publish(first);cycle();need(g.getCost(x,y)==0,"leased isolated seed not removed from temporary master");need(g.getCost(fx,fy)==254,"unleased real obstacle cleared");
 std::this_thread::sleep_for(std::chrono::milliseconds(410));cycle();need(g.getCost(x,y)==254,"expired lease kept hole");publish(first);cycle();need(g.getCost(x,y)==254,"old lease replay revived hole");publish(msg());cycle();need(g.getCost(x,y)==0,"fresh lease not applied");publish(msg(0));cycle();need(g.getCost(x,y)==254,"withdrawal did not restore original source");publish(msg());cycle(4);need(g.getCost(x,y)==254,"large/connected obstacle was ignored");publish(msg(7));cycle();need(g.getCost(x,y)==254,"over-budget lease accepted");auto wrong=msg();wrong.header.frame_id="map";publish(wrong);cycle();need(g.getCost(x,y)==254,"wrong-frame lease accepted");publish(msg());cycle(1,true);need(g.getCost(x,y)==255,"unknown changed to free");publish(msg());g.resetMap(0,0,300,300);g.setCost(x,y,254);unsigned nx,ny;g.worldToMap(1.13,.21,nx,ny);g.setCost(nx,ny,254);double aa2=0,bb2=0,cc2=0,dd2=0;l.updateBounds(0,0,0,&aa2,&bb2,&cc2,&dd2);l.updateCosts(g,0,0,300,300);need(g.getCost(x,y)<254&&g.getCost(nx,ny)==254,"exact 10cm pixel boundary gap rejected or real neighbour cleared");
 std::cout<<"PASS sparse temporary-master lease, expiry/replay, withdrawal, real/large/unknown and budget\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';rclcpp::shutdown();return 1;}rclcpp::shutdown();return 0;}
